4	/// Tracks the ranges of the formatted (including replaced or tokens formatted as verbatim) tokens.
5	///
6	/// This implementation uses the fact that no two tokens can have an overlapping range to avoid the need for an interval tree.
7	/// Thus, testing if a token has already been formatted only requires testing if a token starting at the same offset has been formatted.
8	#[derive(Debug, Clone, Default)]
9	pub struct PrintedTokens {
10	    /// Key: Start of a token's range
11	    offsets: IndexSet<TextSize>,
12	    disabled: bool,
13	}
14	
15	#[derive(Copy, Clone)]
16	pub struct PrintedTokensSnapshot {
17	    len: usize,
18	    disabled: bool,
19	}
20	
21	impl PrintedTokens {
22	    /// Tracks a formatted token
23	    ///
24	    /// ## Panics
25	    /// If this token has been formatted before.
26	    pub fn track_token<L: Language>(&mut self, token: &SyntaxToken<L>) {
27	        if self.disabled {
28	            return;
29	        }
30	
31	        let range = token.text_trimmed_range();
32	        if range.is_empty() {
33	            // Ignore zero-width tokens
34	            return;
35	        }
36	
37	        if !self.offsets.insert(range.start()) {
38	            panic!(
39	                "You tried to print the token '{token:?}' twice, and this is not valid.\
40	                \nYou may need to memoize the token if you are writing it to multiple buffers at the same time."
41	            );
42	        }
43	    }
44	
45	    /// Enables or disables the assertion tracking
46	    pub(crate) fn set_disabled(&mut self, disabled: bool) {
47	        self.disabled = disabled;
48	    }
49	
50	    pub(crate) fn is_disabled(&self) -> bool {
51	        self.disabled
52	    }
53	
54	    pub(crate) fn snapshot(&self) -> PrintedTokensSnapshot {
55	        PrintedTokensSnapshot {
56	            len: self.offsets.len(),
57	            disabled: self.disabled,
58	        }
59	    }
60	
61	    pub(crate) fn restore(&mut self, snapshot: PrintedTokensSnapshot) {
62	        let PrintedTokensSnapshot { len, disabled } = snapshot;
63	
64	        self.offsets.truncate(len);
65	        self.disabled = disabled
66	    }
67	
68	    /// Asserts that all tokens of the passed in node have been tracked
69	    ///
70	    /// ## Panics
71	    /// If any descendant token of `root` hasn't been tracked
72	    pub fn assert_all_tracked<L: Language>(&self, root: &SyntaxNode<L>) {
73	        let mut offsets = self.offsets.clone();
74	
75	        for token in root.descendants_tokens(Direction::Next) {
76	            let range = token.text_trimmed_range();
77	            if range.is_empty() {
78	                // Ignore zero-width tokens
79	                continue;
80	            }
81	
82	            if !offsets.shift_remove(&range.start()) {
83	                panic!(
84	                    "token has not been seen by the formatter: {token:#?}.\
85	                        \nUse `format_replaced` if you want to replace a token from the formatted output.\
86	                        \nUse `format_removed` if you want to remove a token from the formatted output.\n\
87	                        parent: {:#?}",
88	                    token.parent()
89	                )
90	            }
91	        }
92	
93	        if let Some(offset) = offsets.into_iter().next() {
94	            panic!(
95	                "tracked offset {offset:?} doesn't match any token of {root:#?}. Have you passed a token from another tree?"
96	            );
97	        }
98	    }
99	}
