35	impl FormatNodeRule<HtmlClosingElement> for FormatHtmlClosingElement {
36	    fn fmt_fields(&self, node: &HtmlClosingElement, f: &mut HtmlFormatter) -> FormatResult<()> {
37	        let HtmlClosingElementFields {
38	            l_angle_token,
39	            name,
40	            slash_token,
41	            r_angle_token,
42	        } = node.as_fields();
43	
44	        let name = name?;
45	        let css_display = get_css_display_from_tag(&name);
46	        let is_whitespace_sensitive = css_display.is_internally_whitespace_sensitive(f);
47	
48	        // When these tokens are borrowed, they are managed by the sibling `HtmlElementList` formatter.
49	        if !self.tag_borrowed {
50	            // Handle whitespace sensitivity in cases where the HtmlElementList formatter is not invoked because the element has no children.
51	            if let Ok(l_angle_token) = &l_angle_token
52	                && is_whitespace_sensitive
53	                && l_angle_token.has_leading_whitespace_or_newline()
54	            {
55	                // we can't get rid of the whitespace if the element is whitespace sensitive
56	                write!(f, [space()])?;
57	            }
58	
59	            write!(
60	                f,
61	                [l_angle_token.format(), slash_token.format(), name.format()]
62	            )?;
63	        }
64	
65	        // When r_angle_borrowed is true, the `>` will be printed by the next sibling element
66	        if !self.r_angle_borrowed {
67	            write!(f, [r_angle_token.format()])?;
68	        }
69	
70	        Ok(())
71	    }
72	}
